CREATE TEMPORARY VIEW ai_search_srp_seq_info_last_element_${grass_region_without_quote} AS
SELECT
    srp_request_id AS request_id
    ,MAX(algo_intent_search_txt) AS algo_intent_search_txt
    ,ELEMENT_AT(MAX(srp_seq_info), -1) AS srp_seq_info_last_element
