CREATE TEMPORARY VIEW imp_image_id_${grass_region_without_quote} AS
SELECT
    request_id
    ,item_id
    ,location
    ,MAX(image_id) AS imp_image_id
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND page_section IS NULL
    AND target_type = 'item'
    AND operation = 'impression'
    AND original_operation = 'impression'
    AND request_id != ''
    AND item_id IS NOT NULL
    AND location IS NOT NULL
GROUP BY
    1,2,3;

