--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_sqe_mutimodal_real_log_1d 
PARTITION (
    grass_region = ${grass_region},
    grass_date = ${local_date}
)
SELECT
/*+ BROADCASTJOIN(j)*/
    a.user_id
    ,a.item_id
    ,shop_id
    ,content_id
    ,a.request_id
    ,a.search_session_id
    ,search_mid
    ,a.card_type
    ,is_ads
    ,sub_product_type
    ,a.keyword
    ,keyword_type
    ,imp_time
    ,a.location AS item_position
    ,es_score
    ,rank_score AS ranking_score
    ,rule_ids
    ,keyword_cluster AS query_cluster
    ,NAMED_STRUCT('L1', NAMED_STRUCT('cat_id', keyword_cat.level1_category.cat_id, 'cat_name',keyword_cat.level1_category.cat_name), 
        'L2', NAMED_STRUCT('cat_id', keyword_cat.level2_category.cat_id, 'cat_name',keyword_cat.level2_category.cat_name), 
        'L3', NAMED_STRUCT('cat_id', keyword_cat.level3_category.cat_id, 'cat_name',keyword_cat.level3_category.cat_name)) AS query_category
    ,predict_query_category
    ,query_rewrite
    ,query_correct
    ,default_variables
    ,rel_raw
    ,rel_lx
    ,rel_add
    ,audio_url
    ,concat('https://search-dl-ws-latam.img.susercontent.com/', ai_search_info_md5) AS image_url
    ,GET_JSON_OBJECT(ai_search_info_box, '$.box_xy') AS image_bounding_box
    ,user_intention
    ,with_filter
    ,sort_type
    ,platform
    ,search_filter
    ,algo_intent_search_txt
    ,GET_JSON_OBJECT(srp_seq_info_last_element, '$.md5') AS last_md5
    ,FROM_JSON(GET_JSON_OBJECT(srp_seq_info_last_element, '$.box_xy'), 'ARRAY<INT>') AS last_box_xy
    ,GET_JSON_OBJECT(srp_seq_info_last_element, '$.keyword') AS last_keyword
    ,CASE WHEN imp_image_id IS NOT NULL THEN
        CONCAT('https://cf.', region_domain, '/file/https://cf.', region_domain, '/file/', imp_image_id) 
        ELSE NULL END
    AS imp_image_url
FROM
    fe_log_${grass_region_without_quote} AS a
LEFT JOIN
    be_log_${grass_region_without_quote} b
ON
    a.request_id = b.request_id
    AND a.item_id = b.item_id
LEFT JOIN
    dim_item_${grass_region_without_quote} c
ON
    a.item_id = c.item_id
LEFT JOIN
    kw_type_${grass_region_without_quote} d
ON
    a.keyword = d.keyword
LEFT JOIN
    keyword_cat_${grass_region_without_quote} keyword_cat
ON
    a.keyword = keyword_cat.keyword
LEFT JOIN
    deduplicated_qp_log_${grass_region_without_quote} f
ON
    a.request_id = f.request_id
    AND a.user_id = f.user_id
LEFT JOIN
    audio_url_${grass_region_without_quote} g
ON
    a.user_id = g.user_id
    AND a.request_id = g.request_id
    AND a.search_session_id = g.search_session_id
LEFT JOIN
    ai_search_srp_seq_info_last_element_${grass_region_without_quote} h
ON
    a.request_id = h.request_id
LEFT JOIN
    imp_image_id_${grass_region_without_quote} i
ON
    a.request_id = i.request_id
    AND a.item_id = i.item_id
    AND a.location = i.location
LEFT JOIN
    web_domain_${grass_region_without_quote} j;
